self.KB_CONTENT["card:754704"]={"id":"card:754704","ty":"card","sourceId":"754704","title":"『合約訂單建立作業』中的『預交日 (TX016)』為何？","ver":"iGP","topic":"報價單","keywords":["報價單","訂單","複製","單頭"],"y":"other","answer":"* 可空白，若輸入日期，該預交日≧訂單日期。* 若訂單由報價單複製，則預交日期由訂單日期與報價單單頭的交貨日天數來推算。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
