self.KB_CONTENT["card:750546"]={"id":"card:750546","ty":"card","sourceId":"750546","title":"『應收單據清除作業』的作業目的為何？","ver":"iGP","topic":"結帳單","keywords":["結帳單","款單","應收","符合"],"y":"explain","answer":"可將應收單據（結帳單或收款單）資料符合條件，逾期或有誤之資料庫整批清除。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
