self.KB_CONTENT["card:752041"]={"id":"card:752041","ty":"card","sourceId":"752041","title":"『會計異常檢核表』中的『C 帳別科目對應-來源科目內容與目的科目內容不同（指出於帳別資料對應建立作業(ACTI32)中，用途為「2.帳別科目對應」之「來源科目編號」和「目的科目編號」兩者之間的科目資料設定有不同者，如科目性質、資產損益別、報表損益別、科目類別、部門管理、貨幣性科目…等等科目資料的設定）』為何？","ver":"iGP","topic":"資產","keywords":["資產","科目","類別","編號"],"y":"other","answer":"陆、","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
self.KB_CONTENT["card:752131"]={"id":"card:752131","ty":"card","sourceId":"752131","title":"『合併報表基本資料拋轉作業』中的『』為何？","ver":"iGP","topic":"總帳帳別","keywords":["總帳帳別","拋轉","合併","主機"],"y":"other","answer":"拋轉總帳帳本別資料檔* 指是否將總帳帳別資料檔拋轉至母公司主機。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
