self.KB_CONTENT["card:791361"]={"id":"card:791361","ty":"card","sourceId":"791361","title":"『出口費用自動結帳作業』中的『選擇課稅別 (TI024)』為何？","ver":"GP4以上","topic":"課稅別","keywords":["課稅別","結帳","費用","稅率"],"y":"other","answer":"* 區分為1.應稅內含、2.應稅外加、3.零稅率、4.免稅、9.不計稅及A.全部。新增時自動預設應稅外加。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
