self.KB_CONTENT["field:872161"]={"id":"field:872161","ty":"field","sourceId":"872161","title":"生產成本","ver":"iGP 1.0.8.以上","topic":"","keywords":[],"job":"產品成本分析表","code":"","answer":"銷貨之單位成本為當月份的月加權平均單位成本，而產品成本分析表的單位成本僅包含當月份的製令成本，不含月初的數量金額，因此兩者成本不同。","file":"fields.jsonl"};
